('obs_claim_kt10_c04',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='klitos-teklos' LIMIT 1),'shared_authority','Teklos reports to Tory Burch and Pierre-Yves Roussel and partners with Honor Brodie.','distributed_authority','observed','unreviewed',NULL,'The role sits within a shared executive and creative structure.','Do not depict Teklos as replacing or controlling the other leaders.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_kt10_c05',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='klitos-teklos' LIMIT 1),'institutional_boundary','The Tory Burch company, brand, leaders, teams, channels and relevant functions predate the appointment.','institutional_system','observed','unreviewed',NULL,'Teklos entered an established organization and inherited existing functions.','Do not say he created the brand apparatus from zero.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
