('obs_claim_kt10_c07',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='klitos-teklos' LIMIT 1),'economics_boundary','No reviewed record establishes Tory Burch equity, a board seat, compensation, budget authority, employment terms or IP rights for Teklos.','claim_restriction','observed','unreviewed',NULL,'Public evidence establishes appointment and remit, not private economics or ownership.','Absence of public evidence is not proof that no rights exist.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
